import{z as B,x as o,o as r,c as d,q as l,j as i,D as a,d as t,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"GDPR 的技术含义","description":"","frontmatter":{"title":"GDPR 的技术含义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gdpr-technical.md","filePath":"cs/gdpr-technical.md","lastUpdated":1791063341000}'),p={name:"cs/gdpr-technical.md"};function D(c,E,h,m,u,C){const A=o("Mermaid");return r(),d("div",null,[E[2]||(E[2]=l('<h1 id="gdpr-的技术含义" tabindex="-1">GDPR 的技术含义 <a class="header-anchor" href="#gdpr-的技术含义" aria-label="Permalink to &quot;GDPR 的技术含义&quot;">​</a></h1><div class="epigraph"><p>GDPR 把个人数据的合法基础、目的限制、最小化、删除权写成义务。技术含义是：访问控制、留存、可删除架构、跨境、记录处理活动——不是贴合规徽章。</p><footer>—— Regulation (EU) 2016/679；对照 Article 29/EDPB 对技术措施的意见点名</footer></div><p>上一课<a href="/cs/k-anonymity">k-匿名</a>常被误当成合规完成。缺口是<strong>法律义务如何落到系统</strong>：最小化、目的、删除、安全适当。本课技术含义，不是法律咨询。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日志与备份让删除权变难：备份按恢复点成块复制，日志为排障与审计留存、与隐私删除相抵，派生数据（缓存、特征表、训练过的模型）散在管线各处。第 17 条删除权落到工程就是「删除要能传播」。缺口是：数据图、加密与密钥销毁、留存工作流。</p><h3 id="适当安全" tabindex="-1">适当安全 <a class="header-anchor" href="#适当安全" aria-label="Permalink to &quot;适当安全&quot;">​</a></h3><p>第 32 条指向风险相应的技术，假名化与加密被点名为示例措施；恰当性按数据敏感度与规模定档，不是买一张证书。回到本课程的合同：访问控制、加密、审计就是这条的技术库存。</p><p><span class="marginnote">GDPR 正文。脱敏下一课是最小化的工程手段。第 33 条：知悉违约后 72 小时内报监管；第 30 条要记录处理活动（RoPA）；Recital 26 下假名化数据仍是个人数据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把义务翻译成工单：第 6 条合法基础逐用途登记，同一字段不同用途可不同基础；第 5 条最小化收字段，收集时只留必需列；删除传播先画数据图——主库、只读副本、缓存、数仓、<a href="/cs/backup-pitr">备份</a> 各有方案；72 小时违约通知要求告警到法务的路径预先演练；跨境按目的地与传导工具（充分性认定、SCC）区分。列：合法基础记录、最小化字段、删除传播、违约通知时间。下一课脱敏与令牌化。</p><p><span class="marginnote">数字实例：最小化落在表结构上就是砍列——注册流程只负责开账号，就不该顺手存身份证号。每多存一列，删除传播、泄露影响评估、备份过滤都要多做一份工。</span></p>',12)),(r(),i(s,null,{default:a(()=>[n(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PURP%5B%22%E7%9B%AE%E7%9A%84%E9%99%90%E5%88%B6%22%5D%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E5%8C%96%22%5D%0A%20%20MIN%20--%3E%20DEL%5B%22%E5%8F%AF%E5%88%A0%E9%99%A4%E6%9E%B6%E6%9E%84%22%5D%0A%20%20SEC%5B%22%E9%80%82%E5%BD%93%E5%AE%89%E5%85%A8%22%5D%20--%3E%20CTRL%5B%22%E6%9C%AC%E8%AF%BE%E7%A8%8B%E6%8E%A7%E5%88%B6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"法律把隐私当义务，工程问题变成作用域控制：每用户数据密钥（DEK）封装其数据，主库删除时销毁 DEK，散落在不可变存储（备份、日志、对象存储）里的密文随之不可解——crypto-shredding；前提是该类数据全走这条封装。备份的折中：保留期内不解剖已删用户，恢复时按删除清单过滤重建。留存按字段定 TTL，物理删与逻辑删分开。第 25 条「设计与默认」就是最小化进默认配置，与加固课同构。令牌化下一课减少明文持有。",-1)),E[5]||(E[5]=e("p",null,"删除权碰上不可变备份怎么办？crypto-shredding 的答案是删钥匙、不删密文。",-1)),(r(),i(s,null,{default:a(()=>[n(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENC%5B%22%E7%94%A8%E6%88%B7%E6%95%B0%E6%8D%AE%E7%94%A8%E4%B8%93%E5%B1%9E%E5%AF%86%E9%92%A5%20DEK%20%E5%8A%A0%E5%AF%86%22%5D%20--%3E%20STORE%5B%22%E5%AF%86%E6%96%87%E5%86%99%E8%BF%9B%E4%B8%BB%E5%BA%93%E4%B8%8E%E4%B8%8D%E5%8F%AF%E5%8F%98%E5%A4%87%E4%BB%BD%22%5D%0A%20%20DELREQ%5B%22%E7%94%A8%E6%88%B7%E8%A1%8C%E4%BD%BF%E5%88%A0%E9%99%A4%E6%9D%83%22%5D%20--%3E%20DESTROY%5B%22%E5%88%A0%E9%99%A4%E4%B8%BB%E5%BA%93%E8%AE%B0%E5%BD%95%E5%B9%B6%E9%94%80%E6%AF%81%E8%AF%A5%E7%94%A8%E6%88%B7%E7%9A%84%20DEK%22%5D%0A%20%20STORE%20--%3E%20STILL%5B%22%E5%A4%87%E4%BB%BD%E9%87%8C%E7%9A%84%E5%AF%86%E6%96%87%E4%BB%8D%E7%89%A9%E7%90%86%E5%AD%98%E5%9C%A8%22%5D%0A%20%20STILL%20--%3E%20UNREAD%5B%22%E6%B2%A1%E6%9C%89%20DEK%EF%BC%8C%E5%AF%86%E6%96%87%E6%B0%B8%E4%B9%85%E4%B8%8D%E5%8F%AF%E8%A7%A3%22%5D%0A%20%20UNREAD%20--%3E%20EQUAL%5B%22%E5%B7%A5%E7%A8%8B%E4%B8%8E%E8%AE%BA%E8%AF%81%E4%B8%8A%E7%AD%89%E5%90%8C%E5%88%A0%E9%99%A4%22%5D%0A%20%20COND%5B%22%E5%89%8D%E6%8F%90%EF%BC%9A%E8%BF%99%E7%B1%BB%E6%95%B0%E6%8D%AE%E5%85%A8%E8%B5%B0%E5%90%8C%E4%B8%80%E6%9D%A1%E5%8A%A0%E5%AF%86%E5%B0%81%E8%A3%85%22%5D%20--%3E%20ENC%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">术语翻译：crypto-shredding（加密碎纸）就是「把钥匙剪碎」：数据本体在不可变备份里删不动，但解密钥匙一销毁，密文就成了一堆永远读不出的乱码，效果等同删除。</span></p><p><span class="marginnote">常见误区：初学者容易以为「备份里删不掉没关系，反正是旧数据」。GDPR 的删除权不区分主库与备份；工程折中是备份保留期内不解剖已删用户、恢复时按删除清单过滤重建，并把它写进留存策略。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供规避法律的建议。k-匿名不是完成态（回上一课），本课给的是义务到工单的翻译，不是合规结论。脱敏与令牌化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>k-匿名不是 GDPR 完成。</li><li>最小化、目的、删除要架构支持。</li><li>适当安全指向已讲控制。</li><li>下一课脱敏与令牌化。</li><li>出处：Regulation (EU) 2016/679。</li></ul>',6))])}const T=B(p,[["render",D]]);export{P as __pageData,T as default};
